 PCRE2_SIZE capacity=length+1;
 status=pcre2_substitute(r->code,s,n,0,PCRE2_SUBSTITUTE_GLOBAL,r->match,NULL,replacement,rn,b->data,&capacity);
 if(status<0)abort();b->size=capacity;return b;
}
